<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('GET');$user=require_login();$year=max(2020,min(2100,(int)($_GET['year']??date('Y'))));$status=strtoupper(trim((string)($_GET['estatus']??'')));$dep=(int)($_GET['departamento_id']??0);$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$ids=visible_department_ids($db,$user);if($dep>0){if(!user_is_global($user)&&!in_array($dep,$ids,true)){$db->close();json_response(['ok'=>true,'data'=>[]]);}$ids=[$dep];}if(!$ids){$db->close();json_response(['ok'=>true,'data'=>[]]);}$idList=implode(',',array_map('intval',$ids));$where=["ps.ejercicio=$year","ps.departamento_id IN ($idList)"];if(in_array($status,['PENDIENTE','AUTORIZADA','RECHAZADA','PAGADA','CANCELADA'],true))$where[]="ps.estatus='".$db->real_escape_string($status)."'";$sql="SELECT ps.*,d.nombre departamento,s.nombre subitem,CONCAT_WS(' ',u.nombre,u.apellido_paterno,u.apellido_materno) solicitado_por,CONCAT_WS(' ',uo.nombre,uo.apellido_paterno,uo.apellido_materno) otorgado_a FROM presupuesto_solicitud ps JOIN departamento d ON d.departamento_id=ps.departamento_id LEFT JOIN presupuesto_subitem s ON s.subitem_id=ps.subitem_id JOIN usuario u ON u.usuario_id=ps.solicitado_por_usuario_id LEFT JOIN usuario uo ON uo.usuario_id=ps.otorgado_a_usuario_id WHERE ".implode(' AND ',$where)." ORDER BY ps.created_at DESC LIMIT 300";$rs=$db->query($sql);$data=[];while($r=$rs->fetch_assoc()){if(!request_is_visible($db,$user,$r)&&!user_has_permission($user,'SOLICITUD_APROBAR'))continue;$r['solicitud_id']=(int)$r['solicitud_id'];$r['departamento_id']=(int)$r['departamento_id'];$r['subitem_id']=$r['subitem_id']!==null?(int)$r['subitem_id']:null;$r['monto_solicitado']=(float)$r['monto_solicitado'];$data[]=$r;}$db->close();json_response(['ok'=>true,'data'=>$data]);
